import { NextFunction, Request, Response } from "express";
import createUserToken from "../../utils/auth/createUserToken";
import userGetEmailPrisma from "../../utils/db/user/userGetEmailPrisma";
import { compareWithHash } from "../../utils/hashPasswords";
import userViewer from "../../view/userViewer";

/**
 * Users controller for the login function sending a valid jwt token in the response if login is successful.
 * @param req Request with a body property body containing a json with user object with name and email as properties.
 * @param res Response
 */
export default async function userLogin(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const { email, password } = req.body.user;
  try {
    // Get the user with given email
    const user = await userGetEmailPrisma(email);
    if (!user) return res.sendStatus(404);

    // Compare the user password given with the one stored
    console.log(password, user.password);
    if (!compareWithHash(password, user.password)) return res.sendStatus(403);

    // Create the user token for future authentication
    const token = createUserToken(user);

    // Create the user view containing the authentication token
    const userView = userViewer(user, token);

    return res.json(userView);
  } catch (error) {
    return next(error);
  }
}

import { NextFunction, Request, Response } from "express";
import createUserToken from "../../utils/auth/createUserToken";
import userCreatePrisma from "../../utils/db/user/userCreatePrisma";
import { hashPassword } from "../../utils/hashPasswords";
import userViewer from "../../view/userViewer";

/**
 * Users controller that registers the user with information given in the body of the request.
 * @param req Request
 * @param res Response
 * @param next NextFunction
 * @returns
 */
export default async function usersRegister(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const { email, password, username } = req.body.user;
  try {
    // Hash password
    const hashed = hashPassword(password);

    // Create the new user on the database
    const user = await userCreatePrisma(username, email, hashed);

    // Create the authentication token for future use
    const token = createUserToken(user);

    // Create the user view with the authentication token
    const userView = userViewer(user, token);

    return res.status(201).json(userView);
  } catch (error) {
    return next(error);
  }
}

import { NextFunction, Response } from "express";
import { Request } from "express-jwt";
import { ValidationError } from "../../utils/types";

/**
 * Middleware to validate input for article creation controller.
 * @param req Request
 * @param res Response
 * @param next NextFunction
 * @returns void
 */
export default async function articlesCreateValidator(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const errors: ValidationError = {};
  errors.body = [];

  if (!req.body) {
    errors.body.push("can't be empty");
    return res.status(400).json({ errors });
  }

  if (!req.body.article && typeof req.body.article != "object") {
    errors.body.push("article must be an object inside body");
    return res.status(400).json({ errors });
  }

  const { title, description, body, tagList } = req.body.article;

  // Checks if title description and body are present and non-empty strings.
  const requiredChecks = { title, description, body };
  for (const [variable, content] of Object.entries(requiredChecks)) {
    if (typeof content != "string" || content.length == 0) {
      errors.body.push(`${variable} field must be a non-empty string`);
    }
  }

  // Checks if tagList is an array of strings in case it is not undefined.
  if (tagList && !Array.isArray(tagList))
    errors.body.push("tagList must be an array of non-empty strings");
  else if (tagList) {
    let foundError = false;
    for (const tag of tagList) {
      if (typeof tag != "string" || tag.length == 0) {
        foundError = true;
      }
    }
    if (foundError)
      errors.body.push("tagList must be an array of non-empty strings");
  }

  if (errors.body.length) return res.status(400).json({ errors });
  next();
}

