import { NextFunction, Request, Response } from "express";
import { UnauthorizedError } from "express-jwt";
import logger from "../../utils/logger";

/**
 * Middleware that handles authentication errors.
 * @param err Error
 * @param _req Request
 * @param res Response
 * @param next NextFunction
 * @returns void
 */
export default async function authErrorHandler(
  err: Error,
  _req: Request,
  res: Response,
  next: NextFunction
) {
  if (!(err instanceof UnauthorizedError)) return next(err);

  // Se why authorization failed
  logger.debug(`Authorization failed due to ${err.code}`);
  switch (err.code) {
    case "credentials_required":
      return res.sendStatus(401);
    case "credentials_bad_scheme":
      return res.status(400).json({
        errors: { header: ["authorization token with bad scheme"] },
      });
    case "invalid_token":
      return res
        .status(401)
        .json({ errors: { header: ["authorization token is invalid"] } });
    default:
      logger.error(`Unhandled UnauthorizedError with code ${err.code}`);
      return res.sendStatus(500);
  }
}

import { NextFunction, Request, Response } from "express";
import logger from "../../utils/logger";

/**
 * Middleware that handles general errors not handled by other middleware.
 * The last line of defense against errors.
 * @param err Error
 * @param _req Request
 * @param res Response
 * @param _next NextFunction
 * @returns
 */
export default function generalErrorHandler(
  err: Error,
  _req: Request,
  res: Response,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  _next: NextFunction
) {
  // This is an unknown type of error.
  logger.error(`Unhandled error in generalErrorHandler`);
  logger.error(`${err.message}\n${err.name}\n${err.stack}`);
  return res.sendStatus(500);
}

