import { Article, Tag, User } from "@prisma/client";
import profileViewer from "./profileViewer";

type FullArticle = Article & {
  tagList: Tag[];
  author: User & { followedBy: User[] };
  _count: { favoritedBy: number };
};

export default function articleViewer(
  article: FullArticle,
  currentUser?: User & { favorites: Article[] }
) {
  const favorited = currentUser
    ? currentUser.favorites.some((value) => value.slug === article.slug)
    : false;

  const tagListView = article.tagList.map((tag) => tag.tagName).sort();

  const authorView = profileViewer(article.author, currentUser);

  const articleView = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    body: article.body,
    tagList: tagListView,
    createdAt: article.createdAt,
    updatedAt: article.updatedAt,
    favorited: favorited,
    favoritesCount: article._count.favoritedBy,
    author: authorView,
  };
  return articleView;
}

import { Comment, User } from "@prisma/client";
import profileViewer from "./profileViewer";

export default function commentViewer(
  comment: Comment & { author: User & { followedBy: User[] } },
  currentUser?: User
) {
  const commentView = {
    id: comment.id,
    createdAt: comment.createdAt,
    updatedAt: comment.updatedAt,
    body: comment.body,
    author: profileViewer(comment.author, currentUser),
  };
  return commentView;
}

import { User } from "@prisma/client";

type UserWithFollow = User & { followedBy: User[] };

export default function profileViewer(
  user: UserWithFollow,
  currentUser?: User
) {
  const follows = currentUser
    ? Boolean(
        user.followedBy.find((value) => value.username == currentUser.username)
      )
    : false;
  const userView = {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following: follows,
  };
  return userView;
}

import { Tag } from "@prisma/client";

export default function tagViewer(tag: Tag) {
  const tagView = tag.tagName;
  return tagView;
}

